alter table public.garages add column if not exists slug text unique; alter table public.garages add column if not exists booking_enabled boolean not null default true; update public.garages set slug = lower(regexp_replace(nom, '[^a-zA-Z0-9]+', '-', 'g')) where slug is null;
create or replace function public.get_garage_public(p_slug text) returns table (id uuid, nom text, adresse text, telephone text, whatsapp text, logo_url text) language sql stable security definer set search_path = public as $$ select id, nom, adresse, telephone, whatsapp, logo_url from garages where slug = p_slug and booking_enabled; $$;
create or replace function public.get_available_slots(p_slug text, p_date date) returns table (heure text) language plpgsql stable security definer set search_path = public as $$ declare v_garage uuid; v_t time := '08:00'; v_start timestamptz; begin select id into v_garage from garages where slug = p_slug and booking_enabled; if not found then return; end if; if p_date < current_date then return; end if; while v_t <= '17:00' loop v_start := (p_date || ' ' || to_char(v_t, 'HH24:MI'))::timestamp; if not exists (select 1 from appointments a where a.garage_id = v_garage and a.statut <> 'annule' and tstzrange(a.starts_at, a.ends_at) && tstzrange(v_start, v_start + interval '60 minutes')) then heure := to_char(v_t, 'HH24:MI'); return next; end if; v_t := v_t + interval '30 minutes'; end loop; end $$;
create or replace function public.submit_booking(p_slug text, p_nom text, p_telephone text, p_service text, p_date date, p_heure text, p_marque text default null, p_modele text default null, p_immat text default null) returns table (rdv_id uuid, reference text) language plpgsql security definer set search_path = public as $$ declare v_garage uuid; v_client uuid; v_vehicle uuid; v_start timestamptz; v_phone text; v_ref text; begin select id into v_garage from garages where slug = p_slug and booking_enabled; if not found then raise exception 'Garage introuvable'; end if; if coalesce(trim(p_nom), '') = '' or coalesce(trim(p_telephone), '') = '' then raise exception 'Nom et téléphone obligatoires'; end if; v_phone := regexp_replace(p_telephone, '[^\d+]', '', 'g'); v_start := (p_date || ' ' || p_heure)::timestamp; if v_start < now() then raise exception 'Créneau passé'; end if; if exists (select 1 from appointments a where a.garage_id = v_garage and a.statut <> 'annule' and tstzrange(a.starts_at, a.ends_at) && tstzrange(v_start, v_start + interval '60 minutes')) then raise exception 'Créneau déjà pris'; end if; select id into v_client from customers where garage_id = v_garage and regexp_replace(coalesce(telephone,''), '[^\d]', '', 'g') like '%' || regexp_replace(v_phone, '[^\d]', '', 'g') limit 1; if v_client is null then insert into customers (garage_id, nom, telephone) values (v_garage, trim(p_nom), v_phone) returning id into v_client; end if; if coalesce(trim(p_marque), '') <> '' and coalesce(trim(p_modele), '') <> '' then select id into v_vehicle from vehicles where garage_id = v_garage and customer_id = v_client and upper(coalesce(immatriculation, '')) = upper(coalesce(nullif(trim(p_immat), ''), '~')) limit 1; if v_vehicle is null then insert into vehicles (garage_id, customer_id, marque, modele, immatriculation) values (v_garage, v_client, trim(p_marque), trim(p_modele), nullif(trim(p_immat), '')) returning id into v_vehicle; end if; else select id into v_vehicle from vehicles where garage_id = v_garage and customer_id = v_client order by created_at limit 1; if v_vehicle is null then raise exception 'Aucun véhicule trouvé'; end if; end if; insert into appointments (garage_id, customer_id, vehicle_id, service, notes, starts_at, ends_at, statut) values (v_garage, v_client, v_vehicle, p_service, 'Réservation en ligne', v_start, v_start + interval '60 minutes', 'attente') returning id into rdv_id; v_ref := 'RDV-' || to_char(p_date, 'DDMM') || '-' || upper(substr(replace(rdv_id::text, '-', ''), 1, 4)); reference := v_ref; return next; end $$;
create or replace function public.get_repair_status(p_telephone text, p_reference text) returns table (numero text, intervention text, statut public.wo_status, priorite public.wo_priority, mecanicien text, date_entree date, date_sortie_prevue date, vehicule text, garage_nom text, garage_telephone text, historique jsonb) language plpgsql stable security definer set search_path = public as $$ declare v_phone text; v_ref text; begin v_phone := regexp_replace(coalesce(p_telephone, ''), '[^\d]', '', 'g'); v_ref := upper(trim(p_reference)); if length(v_phone) < 8 or v_ref = '' then raise exception 'Données manquantes'; end if; return query select w.numero, w.intervention, w.statut, w.priorite, m.nom, w.date_entree, w.date_sortie_prevue, v.marque || ' ' || v.modele, g.nom, g.telephone, (select coalesce(jsonb_agg(jsonb_build_object('date', to_char(h.created_at, 'DD/MM/YYYY HH24:MI'), 'label', h.label) order by h.created_at), '[]'::jsonb) from work_order_history h where h.work_order_id = w.id) from work_orders w join customers c on c.id = w.customer_id join vehicles v on v.id = w.vehicle_id join garages g on g.id = w.garage_id left join mechanics m on m.id = w.mechanic_id where regexp_replace(coalesce(c.telephone, ''), '[^\d]', '', 'g') like '%' || right(v_phone, 8) and (upper(w.numero) = v_ref or upper(coalesce(v.immatriculation, '')) = v_ref) order by w.created_at desc limit 1; if not found then raise exception 'Dossier introuvable'; end if; end $$;
grant execute on function public.get_garage_public(text) to anon, authenticated; grant execute on function public.get_available_slots(text, date) to anon, authenticated; grant execute on function public.submit_booking(text, text, text, text, date, text, text, text, text) to anon, authenticated; grant execute on function public.get_repair_status(text, text) to anon, authenticated;
